sys_script_include.script:
var VendorDataUtils = Class.create();
VendorDataUtils.prototype = {
    initialize: function() {},


    /**
     * Return true if there is a Scheduled Import for 
     * this data source with a run start after @relativeTo.
     */
    hasScheduledImportAfter: function(scope, dataSourceName, active, gdtRelativeTo) {
        var dataSourceSysId = this.getDataSourceSysId(scope, dataSourceName);
        var gr = new GlideRecord("scheduled_import_set");
        var query = "sys_scope=" + scope;
        query += "^data_source=" + dataSourceSysId;
        if (active) query += "^active=true";
        query += "^run_start>" + gdtRelativeTo;
        gr.addEncodedQuery(query);
        gr.setLimit(1);
        gr.query();
        return gr.hasNext();
    },

    /**
     * Copy all attachments from sys_data_source A to B, and 
     * optionally delete from A
     */
    // shiftAttachments(fromDataSourceName, toDataSourceName, removeOriginals) {
    //     var from_sys_id = this.getDataSourceSysId(scope, fromDataSourceName);
    //     if (!from_sys_id) throw "'From' data source not found.";

    //     var to_sys_id = this.getDataSourceSysId(scope, toDataSourceName);
    //     if (!to_sys_id) throw "'To' data source not found.";

    //     var gsa = new GlideSysAttachment();
    //     gsa.copy("sys_data_source", from_sys_id, "sys_data_source", to_sys_id);

    //     if (removeOriginals) {
    //         var gr = gsa.getAttachments("sys_data_source", from_sys_id);
    //         while (gr.next()) {
    //             gsa.deleteAttachment(gr.getValue("sys_id"));
    //         }
    //     }
    // },

	// copyAttachments: function(sourceTableName, sourceTableSysId, targetTableName, targetTableSysId) {
	// 	var result = [];

	// 	// The row to copy the attachmens to
	// 	var gr_target = new GlideRecord(targetTableName);
	// 	gr_target.get(targetTableSysId);

	// 	// The existing attachments
	// 	var gr_att = new GlideRecord("sys_attachment");
	// 	gr_att.addQuery("table_name", sourceTableName);
	// 	gr_att.addQuery("table_sys_id", sourceTableSysId);
	// 	gr_att.query();
	// 	while(gr_att.next()) {
	// 		var new_sys_id = this.copyAttachment(gr_att, gr_target);
	// 		result.push(new_sys_id);
	// 	}
	// 	return result;
	// },

	copyAttachments: function(gr_attachments, gr_target) {
		var result = [];
		while(gr_attachments.next()) {
			gs.info("Copying attachment " + gr_attachments.getValue("fie_name"));
			var new_sys_id = this.copyAttachment(gr_attachments, gr_target);
			gs.info(new_sys_id);
			result.push(new_sys_id);
		}
		return result;
	},


    copyAttachment: function(gr_source /* source att */, gr_dest /* gr to attach the new file to */) {
        var gsa = new GlideSysAttachment();
        var newAttachmentSysId = gsa.writeContentStream(
            gr_dest,
            gr_source.getValue('file_name'),
            gr_source.getValue('content_type'),
            gsa.getContentStream(gr_source.getValue('sys_id'))
        );
        return newAttachmentSysId;
    },

	deleteAttachments: function(tableName, tableSysId) {
		var delete_sys_ids = [];
		var gr = new GlideRecord("sys_attachment");
		gr.addQuery("table_name", tableName);
		gr.addQuery("table_sys_id", tableSysId);
		gr.query();
		while(gr.next()) delete_sys_ids.push(gr.getValue("sys_id"));
		var gsa = new GlideSysAttachment();
		delete_sys_ids.forEach(e => gsa.deleteAttachment(e));
	},

    createScheduledImport: function(scope, name, dataSourceSysId, runStart, runType) {
        var gr = new GlideRecord("scheduled_import_set");
        gr.initialize();
        gr.setValue("sys_scope", scope);
        gr.setValue("active", true);
        gr.setValue("advanced", false);
        gr.setValue("data_source", dataSourceSysId);
        gr.setValue("name", name);
        gr.setValue("run_start", runStart);
        gr.setValue("run_type", runType);
        gr.update();
    },



    /**
     * Given application scope (sys_id) and the name of 
     * a Data Source, return Data source's sys_id, or null.
     */
    getDataSourceSysId: function(scope, name) {
        var result = null;
        var gr = new GlideRecord("sys_data_source");
        gr.addQuery("sys_scope", scope);
        gr.addQuery("name", name);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) result = gr.getValue("sys_id");
        return result;
    },

    type: 'VendorDataUtils'
};
